#!/usr/bin/env node
// The application template owns its agent guidance. A refresh replaces these
// files, so factory text added to them is lost, and every build formats the
// whole application, so an edit that breaks their formatting fails each task
// once. The overlay records what the template generated; factory CI refuses
// any difference. Factory guidance lives in .github/AGENTS.md.
import { createHash } from 'node:crypto';
import { existsSync, readFileSync } from 'node:fs';
import path from 'node:path';
import process from 'node:process';
import { fileURLToPath } from 'node:url';

export const TEMPLATE_GUIDANCE = ['AGENTS.md', 'CLAUDE.md'];

const sha256 = (data) => createHash('sha256').update(data).digest('hex');

export function guidanceHashes(root) {
  return Object.fromEntries(
    TEMPLATE_GUIDANCE.filter((file) => existsSync(path.join(root, file))).map(
      (file) => [file, sha256(readFileSync(path.join(root, file)))],
    ),
  );
}

// Differences between an application root and the guidance its template
// generated, as recorded in factory-template.json.
export function guidanceDrift(root) {
  const recorded = JSON.parse(
    readFileSync(path.join(root, 'factory-template.json'), 'utf8'),
  ).guidance;
  if (!recorded || typeof recorded !== 'object')
    return ['factory-template.json records no template guidance hashes'];
  const actual = guidanceHashes(root);
  return [...new Set([...Object.keys(recorded), ...Object.keys(actual)])]
    .sort()
    .filter((file) => recorded[file] !== actual[file])
    .map((file) =>
      !(file in actual)
        ? `${file} is missing`
        : !(file in recorded)
          ? `${file} was not generated by the template`
          : `${file} differs from the template's version`,
    );
}

if (
  process.argv[1] &&
  path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)
) {
  const [mode, root] = process.argv.slice(2);
  if (mode !== 'check' || !root) {
    console.error('Usage: template-guidance.mjs check <application-root>');
    process.exit(2);
  }
  const drift = guidanceDrift(path.resolve(root));
  if (drift.length) {
    console.error(
      `${drift.join('\n')}\nThe template owns these files; put factory guidance in .github/AGENTS.md.`,
    );
    process.exit(1);
  }
  console.log('Template guidance matches what the template generated.');
}
